// Noor – Extra Tools: checks the on/off switch, then runs the requested tool.
const input = $('Tool Request').first().json;
const action = String(input.action || '').trim();

// Read switches from the Noor Settings tab (missing or unreadable = OFF).
const on = {};
for (const it of $('Read Noor Settings').all()) {
  const r = it.json || {};
  const k = String(r.feature || '').trim();
  if (k) on[k] = String(r.enabled).trim().toUpperCase() === 'TRUE';
}

// Clinic setup (switch: clinic_setup): owner phone, currency, map pin, prices and instalments from the Sheet.
const SETUP = {};
let PRICE_ROWS = [];
if (on.clinic_setup) {
  try {
    const rows = $('Get Setup').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.tab; })
      .sort(function (a, b) { return Number(a.sort || 0) - Number(b.sort || 0); });
    rows.filter(function (r) { return r.tab === 'clinic'; }).forEach(function (r) { SETUP[r.name] = String(r.value || '').trim(); });
    PRICE_ROWS = rows.filter(function (r) { return r.tab === 'price' && r.value !== '' && !isNaN(Number(r.value)); });
  } catch (e) { /* fallback values */ }
}
const ownerDigits = String(SETUP.owner_phone || '').replace(/\D/g, '');
const OWNER = ownerDigits.length >= 8 ? ownerDigits : '000000000000';
const CUR = SETUP.currency || 'AED';
const INST_MIN = Number(SETUP.instalments_min_total) || 2000;
const INST_MONTHS = Number(SETUP.instalments_months) || 6;

const FEATURE = {
  estimate_price: 'price_estimator', send_location: 'location_pin', running_late: 'running_late', log_cancellation: 'save_cancellation',
  search_knowledge: 'knowledge_base', log_unanswered: 'unanswered_log', log_request: 'request_tracker', approval_status: 'approval_tracker',
  owner_approval: 'approval_tracker', owner_requests_list: 'request_tracker', owner_request_done: 'request_tracker', owner_treatment_plan: 'treatment_followup'
};
// alert_staff: WhatsApp note to the clinic team, logged in Conversations. Test numbers (000000000000xx) never send.
if (action === 'alert_staff') {
  const ph = String(input.phone || '').replace(/\D/g, '');
  if (/^000000000000/.test(ph)) return [{ json: { route: 'done', response: 'Team alerted (test mode).' } }];
  const t = DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm');
  const msg = '[Noor] Patient +' + ph + ': ' + String(input.items || '').slice(0, 500);
  return [{ json: { route: 'append', sheet: 'Conversations', row: { time: t, phone: ph, direction: 'alert', type: 'text', text: msg }, notify_phone: OWNER, notify_text: msg, response: 'The clinic team has been alerted.' } }];
}
const feature = FEATURE[action];
if (!feature) {
  return [{ json: { route: 'done', response: 'Unknown tool.' } }];
}
if (!on[feature]) {
  return [{ json: { route: 'done', response: 'This feature is switched off. Answer the patient normally without it.' } }];
}

const phone = String(input.phone || '').replace(/\D/g, '');
if (action === 'send_location') {
  const lat = Number(SETUP.map_latitude);
  const lng = Number(SETUP.map_longitude);
  return [{ json: {
    route: 'send_location', phone: phone,
    lat: isFinite(lat) && SETUP.map_latitude ? lat : 25.2185,
    lng: isFinite(lng) && SETUP.map_longitude ? lng : 55.2532,
    place: SETUP.clinic_name || 'BrightSmile Dental (demo)',
    address: SETUP.address ? SETUP.address + (SETUP.parking ? '. ' + SETUP.parking + '.' : '') : 'Jumeirah, Dubai, UAE (demo address). Free parking for patients.'
  } }];
}
if (action === 'running_late') {
  return [{ json: { route: 'running_late', phone: phone, owner: OWNER } }];
}
const nowTxt = DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm');
const digits = function (v) { return String(v || '').replace(/\D/g, ''); };
if (action === 'search_knowledge') {
  return [{ json: { route: 'read', sheet: 'Knowledge Base', query: String(input.items || '') } }];
}
if (action === 'approval_status') {
  return [{ json: { route: 'read', sheet: 'Approvals', query: phone } }];
}
if (action === 'owner_requests_list') {
  return [{ json: { route: 'read', sheet: 'Requests', query: '' } }];
}
if (action === 'log_unanswered') {
  return [{ json: { route: 'append', sheet: 'Unanswered', row: { time: nowTxt, phone: phone, question: String(input.items || ''), status: 'new' },
    response: 'Question logged for the team. Tell the patient kindly that a team member will confirm soon, and call alert_staff if you have not already.' } }];
}
if (action === 'log_request') {
  const id = 'R' + DateTime.now().toFormat('ddHHmmss');
  return [{ json: { route: 'append', sheet: 'Requests', row: { key: id, time: nowTxt, phone: phone, type: String(input.service || 'request'), details: String(input.items || ''), status: 'open', updated_at: nowTxt },
    response: 'Request ' + id + ' logged. Tell the patient their request number (' + id + '), that the team will prepare it, and that you will message them when it is ready. Call alert_staff with the request number.' } }];
}
if (action === 'owner_approval') {
  const target = digits(input.minutes);
  const status = String(input.saved || 'pending').toLowerCase().trim();
  if (!target) return [{ json: { route: 'done', response: 'Please include the patient phone number, e.g. #approval 000000000000 approved implant.' } }];
  const row = { key: target, phone: target, treatment: String(input.service || ''), insurer: String(input.reason || ''), status: status, updated_at: nowTxt };
  let notify = '';
  if (status === 'approved') notify = 'Good news! Your insurance approval for ' + (row.treatment || 'your treatment') + ' has been approved. Would you like to book your appointment? Just reply here.';
  if (status === 'rejected') notify = 'Update on your insurance approval for ' + (row.treatment || 'your treatment') + ': unfortunately it was not approved. Our team can explain your options; reply here and we will help.';
  return [{ json: { route: 'append', sheet: 'Approvals', row: row, notify_phone: notify ? target : '', notify_text: notify,
    response: 'Approval for ' + target + ' saved as ' + status + '.' + (notify ? ' The patient is being messaged.' : '') } }];
}
if (action === 'owner_request_done') {
  const id = String(input.items || '').trim().toUpperCase();
  const target = digits(input.minutes);
  if (!id) return [{ json: { route: 'done', response: 'Please include the request number, e.g. #done R10081530.' } }];
  const note = String(input.reason || '').trim();
  return [{ json: { route: 'upsert', sheet: 'Requests', row: { key: id, status: note ? 'done' : 'ready', note: note, updated_at: nowTxt }, notify_phone: target,
    notify_text: note ? 'Update on your request ' + id + ': ' + note : 'Your request ' + id + ' is ready. You can collect it at the clinic, or reply here if you would like it sent another way.',
    response: 'Request ' + id + ' marked ' + (note ? 'done' : 'ready') + '.' + (target ? ' The patient is being messaged.' : ' (No patient phone given, so no message was sent.)') } }];
}
if (action === 'owner_treatment_plan') {
  const target = digits(input.minutes);
  if (!target) return [{ json: { route: 'done', response: 'Please include the patient phone number, e.g. #plan 000000000000 root canal 1500.' } }];
  return [{ json: { route: 'append', sheet: 'Treatment Plans', row: { key: target + '-' + DateTime.now().toFormat('MMddHHmm'), time: nowTxt, phone: target, treatment: String(input.service || ''), price: String(input.items || ''), followups_sent: 0, status: 'open' },
    response: 'Treatment plan saved for ' + target + ' (' + String(input.service || '') + '). Follow-up messages will start once the treatment_followup template is approved.' } }];
}
if (action === 'log_cancellation') {
  const saved = String(input.saved || '').trim().toLowerCase();
  return [{ json: {
    route: 'log_cancellation',
    time: DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm'),
    phone: phone,
    service: String(input.service || ''),
    reason: String(input.reason || ''),
    saved: (saved.startsWith('y') || saved === 'true') ? 'yes' : 'no'
  } }];
}

// ---------- estimate_price ----------
// Built-in prices (fallback). With clinic_setup ON the Prices tab is used instead.
let PRICES = [
  { name: "Children's check-up (age 3+)", price: 120, from: false, words: ['child', 'kid', 'children', 'طفل', 'أطفال', 'اطفال'] },
  { name: 'Same-day emergency appointment', price: 250, from: false, words: ['emergency', 'urgent', 'طوارئ', 'طارئ', 'مستعجل'] },
  { name: 'Root canal treatment', price: 1500, from: true, words: ['root', 'canal', 'عصب'] },
  { name: 'Clear aligners', price: 9000, from: true, words: ['align', 'invisalign', 'brace', 'تقويم'] },
  { name: 'Dental implant', price: 4500, from: true, words: ['implant', 'زراعة', 'زرع'] },
  { name: 'In-clinic teeth whitening', price: 1200, from: false, words: ['whiten', 'bleach', 'تبييض', 'تبيض'] },
  { name: 'Cleaning (scale and polish)', price: 350, from: false, words: ['clean', 'scale', 'polish', 'تنظيف', 'تنضيف'] },
  { name: 'Filling (tooth-coloured)', price: 300, from: true, words: ['fill', 'حشو', 'حشوة', 'حشوات'] },
  { name: 'Extraction', price: 300, from: true, words: ['extract', 'pull', 'removal', 'خلع'] },
  { name: 'Consultation and check-up', price: 150, from: false, words: ['consult', 'check', 'exam', 'كشف', 'فحص', 'استشارة'] }
];
if (PRICE_ROWS.length) {
  PRICES = PRICE_ROWS.map(function (r) {
    return { name: String(r.name), price: Number(r.value), from: /^y/i.test(String(r.option || '')),
      words: String(r.words || '').toLowerCase().split(',').map(function (w) { return w.trim(); }).filter(Boolean),
      freeWithCleaning: /free.*clean/i.test(String(r.notes || '')) };
  });
}
const isCleaning = function (s) { return /clean|scale|تنظيف/i.test(s.name + ' ' + s.words.join(' ')); };
const isConsult = function (s) { return s.freeWithCleaning !== undefined ? s.freeWithCleaning : /^consult/i.test(s.name); };

const parts = String(input.items || '').split(/[,;\n،]+/).map(function (s) { return s.trim(); }).filter(Boolean);
const lines = [];
const unknown = [];
let total = 0;
let anyFrom = false;
let hasCleaning = false;
let consultIndex = -1;

for (const p of parts) {
  const qtyMatch = p.match(/(\d+)/);
  const qty = qtyMatch ? Math.max(1, parseInt(qtyMatch[1], 10)) : 1;
  const text = p.toLowerCase();
  const svc = PRICES.find(function (s) { return s.words.some(function (w) { return text.includes(w); }); });
  if (!svc) { unknown.push(p); continue; }
  const cost = svc.price * qty;
  if (isCleaning(svc)) hasCleaning = true;
  if (isConsult(svc)) consultIndex = lines.length;
  if (svc.from) anyFrom = true;
  total += cost;
  lines.push({ qty: qty, svc: svc, cost: cost });
}

let freeConsult = false;
if (hasCleaning && consultIndex >= 0) {
  freeConsult = true;
  total -= lines[consultIndex].cost;
  lines[consultIndex].cost = 0;
}

const out = lines.map(function (l) {
  const each = l.qty > 1 ? ' (' + CUR + ' ' + l.svc.price.toLocaleString('en-US') + ' each)' : '';
  const price = l.cost === 0 && freeConsult ? 'FREE with the cleaning' : (l.svc.from ? 'from ' : '') + CUR + ' ' + l.cost.toLocaleString('en-US');
  return '- ' + l.qty + ' x ' + l.svc.name + ': ' + price + each;
});

let response = out.length ? out.join('\n') + '\n' + (anyFrom ? 'Estimated total: from ' + CUR + ' ' : 'Total: ' + CUR + ' ') + total.toLocaleString('en-US') : 'No services from the price list were recognised.';
if (anyFrom) response += '\n"From" prices are starting prices; the dentist confirms the final price after the check-up.';
if (unknown.length) response += '\nNot in the price list (a team member will confirm): ' + unknown.join(', ');
// Instalments (switch: instalments): 0% over N months for totals above the minimum.
if (on['instalments'] && total > INST_MIN) {
  const monthly = Math.ceil(total / INST_MONTHS);
  response += '\n0% instalments: ' + (anyFrom ? 'from ' : '') + CUR + ' ' + monthly.toLocaleString('en-US') + '/month for ' + INST_MONTHS + ' months (no interest).';
}
return [{ json: { route: 'done', response: response } }];

// Running late: compares the patient's arrival time with today's appointment and prepares the staff alert.
const input = $('Tool Request').first().json;
const p = $('Find Patient (Late)').first().json || {};
const phone = String(input.phone || '').replace(/\D/g, '');
const minutes = Math.max(0, parseInt(String(input.minutes || '0').replace(/[^0-9]/g, ''), 10) || 0);
const now = DateTime.now().setZone('Asia/Dubai');
const eta = now.plus({ minutes: minutes });
const name = p.name || 'A patient';
const status = String(p.status || '').toLowerCase();

let start = null;
if (p.appointment_start && (status === 'booked' || status === 'confirmed')) {
  const s = DateTime.fromFormat(String(p.appointment_start), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
  if (s.isValid && s.hasSame(now, 'day')) start = s;
}

if (!start) {
  return [{ json: {
    alert: 'Running late: ' + name + ' (' + phone + ') says they will arrive in about ' + minutes + ' min (around ' + eta.toFormat('HH:mm') + '), but no appointment today was found. Please check.',
    response: 'No appointment for today was found for this patient. Tell them kindly that the team has been informed, and ask which appointment they mean.'
  } }];
}

const lateBy = Math.round(eta.diff(start, 'minutes').minutes);
const appt = (p.service || 'appointment') + ' at ' + start.toFormat('HH:mm') + (p.dentist ? ' with ' + p.dentist : '');
const alert = 'Running late: ' + name + ' (' + phone + '), ' + appt + '. Expected arrival ' + eta.toFormat('HH:mm') + (lateBy > 0 ? ' (' + lateBy + ' min late).' : ' (on time).');
let response;
if (lateBy <= 0) {
  response = 'They will arrive on time for their ' + appt + '. Reassure them; the team knows they are on the way.';
} else if (lateBy <= 15) {
  response = 'They will be about ' + lateBy + ' minutes late for their ' + appt + '. That is within the 15-minute grace period. Reassure them warmly; the team has been told.';
} else {
  response = 'They will be about ' + lateBy + ' minutes late for their ' + appt + ', more than the 15-minute limit. Kindly explain that arriving more than 15 minutes late may need rescheduling, that the team has been told and will confirm if they can still be seen, and offer to find a new time with find_free_slots.';
}
return [{ json: { alert: alert, response: response } }];

// Builds the tool answer from a sheet tab (knowledge base search, approval status, open requests).
const req = $('Check Switch and Run').first().json;
const input = $('Tool Request').first().json;
const rows = $input.all().map(function (i) { return i.json || {}; }).filter(function (r) { return !r.error && Object.keys(r).length; });
const digits = function (v) { return String(v || '').replace(/\D/g, ''); };
const action = String(input.action || '');
let response = '';

if (action === 'search_knowledge') {
  const q = String(req.query || '').toLowerCase();
  const scored = rows.map(function (r) {
    const kws = String(r.keywords || '').toLowerCase().split(',').map(function (k) { return k.trim(); }).filter(Boolean);
    let score = 0;
    kws.forEach(function (k) { if (q.includes(k)) score += k.split(' ').length + 1; });
    String(r.topic || '').toLowerCase().split(/[^a-z؀-ۿ]+/).forEach(function (w) { if (w.length > 3 && q.includes(w)) score += 1; });
    return { r: r, score: score };
  }).filter(function (x) { return x.score > 0; }).sort(function (a, b) { return b.score - a.score; }).slice(0, 2);
  response = scored.length
    ? scored.map(function (x) { return x.r.topic + ': ' + x.r.answer; }).join('\n')
    : 'Nothing about this in the knowledge base. Tell the patient a team member will confirm soon, call alert_staff, and call log_unanswered with the question.';
} else if (action === 'approval_status') {
  const mine = rows.filter(function (r) { return digits(r.phone) === digits(input.phone); });
  if (!mine.length) response = 'No insurance approval request found for this patient yet. Offer to check with the team (call alert_staff).';
  else {
    const a = mine[mine.length - 1];
    response = 'Insurance approval for ' + (a.treatment || 'their treatment') + (a.insurer ? ' with ' + a.insurer : '') + ': ' + (a.status || 'pending') + ' (last update ' + (a.updated_at || '') + ').' + (String(a.status).toLowerCase() === 'approved' ? ' Offer to book the appointment.' : '');
  }
} else if (action === 'owner_requests_list') {
  // Closed requests (ready, done or closed) are not listed.
  const open = rows.filter(function (r) { return ['ready', 'done', 'closed'].indexOf(String(r.status || '').toLowerCase().trim()) < 0; });
  response = open.length ? 'Open requests:\n' + open.map(function (r) { return r.key + ' | ' + r.phone + ' | ' + r.type + ' | ' + (r.details || '') + ' | since ' + r.time; }).join('\n') : 'No open requests.';
}
return [{ json: { response: response } }];

// Test phones (9715000009...) come from the Test Suite: answer normally but never write to the Sheet or message anyone.
const r = $input.first().json || {};
const ph = String($('Tool Request').first().json.phone || '').replace(/\D/g, '');
if (/^000000000000/.test(ph) && ['append', 'upsert', 'log_cancellation', 'running_late'].indexOf(String(r.route)) >= 0) {
  const resp = r.response || (r.route === 'running_late' ? 'The team has been told they are running late (test mode).' : r.route === 'log_cancellation' ? 'Cancellation reason logged (test mode).' : 'Saved (test mode).');
  return [{ json: { route: 'done', response: resp } }];
}
return [{ json: r }];
